print(([an:=[sq:=set(sqr*sqr for sqr in range(1, 50000)),wr:=[i for i in open("p98_words.txt", "r").read().replace('"', "").split(",")], l:=__import__("collections").Counter(map(lambda w: "".join(sorted(w)), wr))]*0 + [k for k in l.keys() if l[k]>1], pr:= [[j for j in wr if "".join(sorted(j))==s] for s in an], ch:=(lambda chk: [sqstr := [str(x) for x in sq]]*0 + [s for s in sqstr if len(s) == len(chk) and len(set(s)) == len(s)]), repl := (lambda ll, mp: ([nc:="".join([mp[ll[0].index(rtem)] for rtem in ll[1]])]*0 + [len(str(int(nc)))==len(ll[0]) and int(nc) in sq])[0]), ch2 := (lambda lll: any([repl(lll, mapping) for mapping in ch(lll[0])])), pr2:= [p for p in pr if ch2(p)], rep2 := (lambda llz: max([max(int(mpz), int("".join([dict(zip(llz[0], mpz))[c] for c in llz[1]]))) for mpz in ch(llz[0]) if repl(llz, mpz)]))]*0 + [max([rep2(fx) for fx in pr2])])[0]) #arun, 12/05/26